def transform(grid):
    g = np.array(grid)
    h, w = g.shape
    out = np.zeros((3 * h, 3 * w), dtype=int)
    emit(out, "Allocate a 3x-size canvas filled with 0")

    # find the solid single-colour line: a row or a column
    solid_row = None
    solid_col = None
    for y in range(h):
        if len(set(g[y, :].tolist())) == 1:
            solid_row = y
            break
    if solid_row is None:
        for x in range(w):
            if len(set(g[:, x].tolist())) == 1:
                solid_col = x
                break

    if solid_row is not None:
        # tile horizontally along the solid row, in the band of rows 3*i .. 3*i+2
        y0 = solid_row * h
        for k in range(3):
            out[y0:y0 + h, k * w:(k + 1) * w] = g
            emit(out, f"Solid row {solid_row}: stamp copy {k+1} of the input horizontally into row band {y0}-{y0+h-1}")
    else:
        if solid_col is None:
            solid_col = 0
        # tile vertically along the solid column, in the band of columns 3*i .. 3*i+2
        x0 = solid_col * w
        for k in range(3):
            out[k * h:(k + 1) * h, x0:x0 + w] = g
            emit(out, f"Solid column {solid_col}: stamp copy {k+1} of the input vertically into column band {x0}-{x0+w-1}")

    emit(out, "Final canvas")
    return out
